<template>
  <section class="card min-w-0 text-gray-800 dark:text-gray-100 space-y-5 p-4 md:p-6" data-payment-matches>
    <header class="flex flex-wrap justify-between gap-2"><h2 class="font-semibold">購入と支払いの照合</h2><button class="text-sm text-primary-main dark:text-primary-light" :disabled="busy" @click="load">再読み込み</button></header>
    <p v-if="error" role="alert" class="break-words text-sm text-red-600 dark:text-red-300">{{ error }}</p><p v-if="message" role="status" class="text-sm text-green-700 dark:text-green-300">{{ message }}</p>
    <template v-if="recordData">
      <div class="rounded-xl bg-gray-50 p-4 text-sm dark:bg-gray-800" data-record-payment-totals><p>購入金額 {{ cash(recordData.totals.total,recordData.totals.currency) }} · 支払 {{ cash(recordData.totals.paid,recordData.totals.currency) }} · 返金 {{ cash(recordData.totals.refunded,recordData.totals.currency) }}</p><p class="mt-2 font-medium" :class="recordData.totals.state==='overpaid'?'text-amber-700 dark:text-amber-300':''">{{ recordData.totals.state==='overpaid'?'過払い・要確認':'残額' }} {{ cash(recordData.totals.remaining,recordData.totals.currency) }}</p><p v-if="recordData.totals.otherCurrency.length" class="mt-2 text-amber-700 dark:text-amber-300">他通貨の支払いがあります。通貨が異なるため、受付通貨の金額がない配分は差額に含めません。</p></div>
      <div class="space-y-2"><p class="text-sm font-medium">この購入に照合した支払い</p><p v-if="!recordData.allocations.length" class="text-sm text-gray-500">照合した支払いはまだありません。</p><button v-for="a in recordData.allocations" :key="a.id" class="block w-full rounded-lg border border-gray-200 p-3 text-left text-sm dark:border-gray-700" @click="open(a.payment.endpoint)">{{ a.payment.date }} · {{ a.payment.description }} · {{ cash(a.amount,a.currency) }} {{ a.status==='released'?'（解除済み）':'' }}</button></div>
      <details><summary class="cursor-pointer text-sm text-primary-main dark:text-primary-light">支払いの候補を表示</summary><button v-for="c in recordData.candidates" :key="c.payment.paymentKey" class="mt-2 block w-full rounded-lg bg-gray-50 p-3 text-left text-sm dark:bg-gray-800" @click="open(c.payment.endpoint)">{{ c.payment.description }} · {{ cash(c.payment.amount,c.payment.currency) }} · {{ c.candidate.label }}</button></details>
    </template>
    <template v-if="data">
      <div class="rounded-xl bg-gray-50 p-4 dark:bg-gray-800"><p class="text-xs text-gray-500">{{ data.payment.accountName }} · {{ data.payment.date || '日付未記載' }}</p><p class="mt-1 break-words font-medium">{{ data.payment.description }}</p><p class="mt-2 text-sm">{{ cash(data.payment.amount,data.payment.currency) }} · 未配分 {{ cash(data.payment.remaining,data.payment.currency) }}</p><p v-if="data.payment.state==='review'" class="mt-2 text-sm text-amber-700 dark:text-amber-300">要確認：変更された原本・過払い・配分を確認してください。</p></div>
      <template v-if="data.payment.sourceKind==='repayment'"><p class="text-sm leading-relaxed">Amexは請求額・振替日を含まないため、口座振替行（前回分口座振替金額）で照合します。銀行の出金側から、返済行と対象の請求期間を確認してください。</p><p v-if="!data.settledBy.length" class="text-sm text-gray-500">この返済に照合した銀行明細はまだありません。</p><button v-for="s in data.settledBy" :key="s.allocation.id" class="block text-sm text-primary-main dark:text-primary-light" @click="open(s.payment.endpoint || 'payments/bank/'+s.payment.bankRowId)">{{ s.payment.date }} · {{ s.payment.description }} · {{ cash(s.allocation.amount,s.allocation.currency) }}</button></template>
      <template v-else>
        <div class="space-y-2"><h3 class="text-sm font-medium">購入の候補</h3><p v-if="!data.candidates.length" class="text-sm text-gray-500">一致する候補はありません。購入受付を検索して手動で指定できます。</p><button v-for="c in data.candidates" :key="c.record.id" class="block w-full rounded-lg border p-3 text-left text-sm" :class="c.rank==='strong'?'border-primary-main/40 bg-primary-main/5':'border-gray-200 dark:border-gray-700'" :data-match-record="c.record.id" @click="choose(c.target,c.record,c)"><span class="block break-words font-medium">{{ c.record.values.description || c.record.values.externalOrderId || c.record.values.orderId || '購入受付' }}</span><span class="mt-1 block text-xs text-gray-500">{{ c.label }} · {{ c.reasons.map(reasonName).join(' / ') }}</span><span class="mt-1 block break-words text-xs">{{ c.record.evidence?.supplierName }} {{ c.record.evidence?.invoiceNumber }}</span></button></div>
        <label class="block text-sm">購入受付を検索<input type="text" v-model="search" class="input max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white mt-1 w-full" placeholder="注文番号・購入先・商品名"><select class="input max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white mt-2 w-full" data-manual-record value="" @change="manual($event)"><option value="">購入を選択してください</option><option v-for="r in manualRecords" :key="r.id" :value="r.id">{{ r.values.orderId }} {{ r.values.description || r.values.externalOrderId }} · {{ r.values.amount || '金額未確定' }} {{ r.values.currency }}</option></select></label>
        <div v-if="data.payment.kind==='bank'" class="space-y-2"><h3 class="text-sm font-medium">カードの返済・請求期間への照合</h3><p class="text-xs leading-relaxed text-gray-500">個別購入と別の資金移動として管理します。Amexの請求期間は自動確定されません。手動照合は根拠のメモを残します。</p><button v-for="(s,i) in data.settlements" :key="i" class="block w-full rounded-lg border border-gray-200 p-3 text-left text-sm dark:border-gray-700" :data-settlement="i" @click="choose(s.target,null,s)">{{ s.target.kind==='card-repayment'?'口座振替行':s.target.statementMonth || s.target.periodKey }} · {{ s.label }}<span v-if="s.suggestedCoversImportId" class="mt-1 block text-xs text-amber-700 dark:text-amber-300">対象期間の候補あり・要確認（未選択）</span></button></div>
        <form v-if="chosen" class="space-y-3 rounded-xl border border-primary-main/30 p-4" @submit.prevent="confirmAllocation">
          <h3 class="text-sm font-medium">配分を確認</h3><p class="break-words text-sm">{{ chosen.record?.values.description || chosen.record?.values.orderId || chosen.proposal?.label || '手動で選択した購入' }}</p>
          <label class="block text-sm">配分金額（{{ data.payment.currency }}・返金はマイナス）<input v-model="amount" class="input max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white mt-1 w-full" type="number" step="0.01" required data-allocation-amount></label>
          <label v-if="chosen.record && chosen.record.values.currency!==data.payment.currency" class="block text-sm">受付通貨の金額（{{ chosen.record.values.currency }}・任意）<input v-model="recordAmount" class="input max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white mt-1 w-full" type="number" step="0.01"><span class="mt-1 block text-xs text-gray-500">空欄なら通貨が異なるため残額に含めません。為替換算は行いません。</span></label>
          <label v-if="chosen.target.kind==='card-repayment'" class="block text-sm">この返済が支払った請求期間（任意・要確認）<select v-model="coversImportId" class="input max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white mt-1 w-full"><option value="">期間を指定しない</option><option v-for="s in data.settlements.filter((s:any)=>s.target.kind==='card-statement' && s.target.accountId===chosen.target.accountId)" :key="s.target.importId" :value="s.target.importId">{{ s.target.statementMonth || s.target.periodKey }}</option></select></label>
          <label class="block text-sm">確認した根拠・メモ<textarea v-model="note" class="input max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white mt-1 w-full" maxlength="2000" :required="chosen.proposal?.evidence==='manual'" /></label>
          <p class="text-xs text-gray-500">照合先と金額を確認して保存します。仕訳・振込は実行されません。</p><div class="flex flex-wrap gap-2"><button class="btn btn-primary" :disabled="busy || disabled" data-allocation-confirm>確認して配分を保存</button><button type="button" class="btn btn-secondary" @click="chosen=null">取り消す</button></div>
        </form>
      </template>
      <div class="space-y-3"><h3 class="text-sm font-medium">配分と根拠・履歴</h3><p v-if="!data.allocations.length" class="text-sm text-gray-500">まだ配分はありません。</p><article v-for="a in data.allocations" :key="a.id" class="rounded-xl border border-gray-200 p-4 text-sm dark:border-gray-700" :data-allocation="a.id"><p class="break-words">{{ a.record?.values.description || a.record?.values.orderId || (a.target.kind==='card-repayment'?'カード返済':'カード請求期間') }} · {{ cash(a.amount,a.currency) }} · {{ a.status==='linked'?'照合済み':'解除済み' }}</p><template v-if="a.record"><NuxtLink :to="'/intake/'+a.record.id" class="mt-2 block text-primary-main dark:text-primary-light">購入と原本を開く</NuxtLink><p class="mt-2 break-words" data-allocation-evidence>{{ a.record.evidence?.supplierName || '会社未確認' }} · {{ a.record.evidence?.invoiceNumber || 'T番号未確認' }}</p><p class="text-xs text-gray-500">{{ a.record.evidence?.confirmed?'受付に保存済み':'調査候補' }} · {{ a.record.evidence?.verified?'国税庁照合済み':'国税庁未照合・未確認' }}</p><a v-for="s in (a.record.evidence?.research?.sources || []).filter((s:any)=>safeUrl(s.url))" :key="s.id" :href="safeUrl(s.url) || undefined" target="_blank" rel="noopener noreferrer" class="mt-1 block break-words text-xs text-primary-main dark:text-primary-light">{{ s.title || s.url }}</a><p v-if="a.record.archived" class="mt-2 text-amber-700">受付はアーカイブ済みです。</p></template><p v-if="a.note" class="mt-2 break-words text-xs text-gray-500">{{ a.note }}</p><p v-if="a.changed || a.sourceChanged" class="mt-2 text-amber-700 dark:text-amber-300">元の情報が変更されました。変更を確認して再確認または解除してください。{{ a.changes.map((d:any)=>d.field+': '+d.before+' → '+d.after).join(' / ') }}</p><div v-if="a.status==='linked'" class="mt-3 flex flex-wrap gap-3"><button v-if="a.changed || a.sourceChanged" class="text-primary-main dark:text-primary-light" :disabled="busy || disabled" @click="act(a,'reconfirm')">変更を確認して再確認</button><button class="text-red-600 dark:text-red-300" :disabled="busy || disabled" @click="act(a,'release')">照合を解除</button></div><details class="mt-2 text-xs text-gray-500"><summary class="cursor-pointer">操作履歴（{{ a.history.length }}件）</summary><p v-for="(h,i) in a.history" :key="i">{{ h.at }} · {{ h.action }}</p></details></article></div>
      <div v-for="g in data.statementRecords" :key="g.allocationId" class="space-y-1 rounded-lg bg-gray-50 p-3 text-sm dark:bg-gray-800"><p class="font-medium">このカード期間で照合した購入・T番号</p><p v-if="!g.records.length" class="text-gray-500">個別購入の照合はまだありません。</p><NuxtLink v-for="(r,i) in g.records" :key="i" :to="'/intake/'+r.id" class="block break-words text-primary-main dark:text-primary-light">{{ r.values.description }} · {{ r.evidence.supplierName }} {{ r.evidence.invoiceNumber }}</NuxtLink></div>
      <template v-if="data.payment.kind==='bank'"><details><summary class="cursor-pointer text-sm">元ファイルの行（{{ data.payment.provenance.length }}件）</summary><p v-for="(s,i) in data.payment.provenance" :key="i" class="mt-1 break-all text-xs text-gray-500">{{ s.sheet }} · {{ s.row }}行 · {{ s.hash }}</p></details><div v-if="data.pairs.length" class="space-y-2"><h3 class="text-sm font-medium">重複・訂正の確認</h3><p class="text-xs text-gray-500">同じ金額・摘要でも別の支払いの場合があります。同一の取引と確認できた場合のみ統合してください。両方の配分と履歴を保持します。</p><label class="block text-sm">統合する元の明細<select v-model="supersedes" class="input max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white mt-1 w-full"><option value="">選択してください</option><option v-for="p in data.pairs" :key="p.oldId" :value="p.oldId">{{ p.label }} · {{ data.bankRows.find((r:any)=>r.id===p.oldId)?.description }} · {{ p.oldId.slice(-6) }}</option></select></label><button class="btn btn-secondary" :disabled="!supersedes || busy || disabled" data-bank-confirm-correction @click="confirmCorrection">同じ取引と確認して、この明細に統合</button></div></template>
    </template>
    <p v-if="loading" class="text-sm text-gray-500">読み込み中…</p>
  </section>
</template>
<script setup lang="ts">
import { useUserStore } from '~/stores/user'
const props=defineProps<{side:'record'|'card'|'payment';recordId?:string;record?:any;importId?:string;line?:number;endpoint?:string;disabled?:boolean}>(),emit=defineEmits<{(e:'changed'):void;(e:'ready'):void}>(),user=useUserStore(),api='/api/finance-payments/'
const recordData=ref<any>(null),data=ref<any>(null),activeEndpoint=ref(''),loading=ref(false),busy=ref(false),error=ref(''),message=ref(''),chosen=ref<any>(null),amount=ref(''),recordAmount=ref(''),note=ref(''),coversImportId=ref(''),search=ref(''),supersedes=ref(''),requestId=ref('')
const cash=(v:any,c:string)=>v===null||v===undefined?'金額未確定':Number(v).toLocaleString('ja-JP')+' '+c
const reasonName=(v:string)=>({reference:'注文番号',amount:'金額',date:'日付',merchant:'購入先','currency-differs':'通貨の違い'} as Record<string,string>)[v]||v
const manualRecords=computed(()=>(data.value?.manualRecords||[]).filter((r:any)=>Object.values(r.values).join(' ').toLowerCase().includes(search.value.toLowerCase())).slice(0,100))
function safeUrl(url:string){try{const u=new URL(url);return u.protocol==='https:'||u.protocol==='http:'?u.href:null}catch{return null}}
function failure(e:any){return e.data?.data?.message||e.data?.statusMessage||e.message||'処理に失敗しました。再試行してください。'}
async function load(){loading.value=true;error.value='';try{if(props.side==='record')recordData.value=await $fetch(api+'records/'+props.recordId,{headers:user.authHeader});if(props.side==='card'&&!activeEndpoint.value)activeEndpoint.value='payments/card/'+props.importId+'/'+props.line;if(props.side==='payment'&&!activeEndpoint.value)activeEndpoint.value=props.endpoint||'';if(activeEndpoint.value)data.value=await $fetch(api+activeEndpoint.value,{headers:user.authHeader})}catch(e:any){error.value=failure(e)}finally{loading.value=false;emit('ready')}}
async function open(endpoint:string){activeEndpoint.value=endpoint;chosen.value=null;await load()}
function choose(target:any,record:any,proposal:any){chosen.value={target,record,proposal};const remaining=record?.totals?.remaining;amount.value=String(Math.sign(data.value.payment.amount)*Math.min(Math.abs(data.value.payment.remaining),remaining>0?remaining:Math.abs(data.value.payment.remaining)));recordAmount.value='';note.value='';coversImportId.value='';requestId.value=crypto.randomUUID();message.value=''}
function manual(event:Event){const el=event.target as HTMLSelectElement,r=data.value.manualRecords.find((r:any)=>r.id===el.value);if(r)choose({kind:'intake',recordId:r.id,recordKey:r.key},r,null);el.value=''}
async function mutate(fn:()=>Promise<any>){busy.value=true;error.value='';try{await fn();chosen.value=null;supersedes.value='';await load();message.value='保存しました。';emit('changed')}catch(e:any){const text=failure(e);if((e.statusCode||e.status)===409){chosen.value=null;await load()}error.value=text}finally{busy.value=false}}
async function confirmAllocation(){await mutate(()=>$fetch(api+activeEndpoint.value+'/allocations',{method:'POST',headers:user.authHeader,body:{confirm:true,requestId:requestId.value,target:{...chosen.value.target,...(coversImportId.value?{coversImportId:coversImportId.value}:{})},paymentRevision:data.value.payment.paymentRevision,recordRevision:chosen.value.record?.revision,amount:amount.value,...(recordAmount.value!==''?{recordAmount:recordAmount.value}:{}),note:note.value}}))}
async function act(a:any,action:string){await mutate(()=>$fetch(api+activeEndpoint.value+'/allocations/'+a.id,{method:'PUT',headers:user.authHeader,body:{confirm:true,action,paymentRevision:data.value.payment.paymentRevision,recordRevision:a.record?.revision}}))}
async function confirmCorrection(){await mutate(()=>$fetch(api+'bank/rows/'+data.value.payment.bankRowId,{method:'PUT',headers:user.authHeader,body:{confirm:true,supersedes:supersedes.value,revision:data.value.payment.rowRevision}}))}
onMounted(load)
watch(()=>props.record?.revision,()=>{if(recordData.value)load()})
</script>
